/* Field-level explanation for the Spare Parts inventory flow. */
(function(){
  function stockFlowGuide(){return `<section class="partsStockGuide panel"><div class="panelhead"><h2>${icon('box')} How Spare Parts Stock Updates</h2></div><div class="panelbody"><p class="partsStockGuideIntro">Main Stock is the quantity available for Job Cards and counter sales.</p><div class="partsStockFormula"><strong>Main Stock</strong><span>Opening Stock + Main Purchases + Transfers In − Sales / Used</span></div><div class="partsStockGuideGrid"><article><h3>Opening Stock</h3><p>Starting quantity entered in Spare Parts. It is added to Main Stock.</p></article><article><h3>Purchase</h3><p>Purchase stock goes to the location selected in the purchase entry. Godown stock reaches Main Stock only after transfer.</p></article><article><h3>Transfer In</h3><p>Stock moved from Godown to Main Stock. Godown decreases and Main Stock increases by the same quantity.</p></article><article><h3>Sales / Used</h3><p>Stock consumed by a saved Job Card or Spare Parts Sale. It reduces Main Stock; it is not a Godown transfer.</p></article><article><h3>Main Stock</h3><p>Current stock available for new Job Cards and sales. The system calculates it automatically.</p></article><article><h3>Low Stock</h3><p>The warning appears when Main Stock reaches the minimum level. Zero means Out of Stock.</p></article></div><p class="partsStockGuideNote"><strong>Prices:</strong> Each purchase keeps its own purchase cost. Selling Price is the rate used when the part is sold or used.</p><p class="partsStockGuideNote"><strong>History:</strong> Use Movement History to review purchases, transfers and stock used.</p></div></section>`}
  const renderBeforePartsStockGuide=render;
  render=function(){const result=renderBeforePartsStockGuide();if(page==='parts'&&!$('#partsStockFlowGuide')){$('#content').insertAdjacentHTML('beforeend',stockFlowGuide().replace('class="partsStockGuide panel"','id="partsStockFlowGuide" class="partsStockGuide panel"'))}return result};
  if(page==='parts')render();
})();
